import itertools
vals = set()
# brute force over integer lists with the given sums
for a, b in itertools.product(range(0, 46), repeat=2):
    c = 45 - a - b
    if c < 0:
        continue
    for d in range(0, 67):
        e = 66 - c - d
        if e < 0:
            continue
        if a + b + c + d + e == 90:
            vals.add(c)
assert len(vals) == 1
ans = vals.pop()

